 {page==='New application'&&<div className="panel form-panel"><span className="eyebrow">STEP 1 · APPLICATION TYPE</span><h1>Choose what your institution needs</h1><p>Select the application type and upload every required document before submitting. The evaluation track is selected automatically.</p><label>Application type<select aria-label="Application type" value={kind} onChange={e=>{setKind(e.target.value);setNewApplicationFiles({})}}>{Object.entries(rules.types).sort(([,a],[,b])=>String((a as Row).label).localeCompare(String((b as Row).label))).map(([key,value])=><option key={key} value={key}>{(value as Row).label}</option>)}</select></label>{rules.types[kind]&&<div className="info"><ShieldCheck size={20}/><span><b>Evaluation track: {rules.types[kind].track}</b><br/>{rules.source}. Required documents must be uploaded before submission.</span></div>}<div className="required-documents"><h3>Required documents</h3>{rules.types[kind]?.slots.map((slot:string)=><label key={slot}>{slot}<input type="file" accept=".pdf,.txt,application/pdf,text/plain" aria-label={'Upload '+slot} onChange={e=>{const file=e.target.files?.[0];if(file)setNewApplicationFiles(previous=>({...previous,[slot]:file}))}}/><small>{newApplicationFiles[slot]?.name||'No file selected'}</small></label>)}</div><button disabled={busy||!rules.types[kind]||rules.types[kind].slots.some((slot:string)=>!newApplicationFiles[slot])} onClick={()=>run(async()=>{const created=await api('/applications','POST',{kind,idempotency_key:Array.from(crypto.getRandomValues(new Uint8Array(16))).map(n=>n.toString(16).padStart(2,'0')).join('')});let version=created.version;for(const slot of rules.types[kind].slots){const form=new FormData();form.append('slot',slot);form.append('version',String(version));form.append('file',newApplicationFiles[slot]);const uploaded=await api('/applications/'+created.id+'/documents','POST',form);version=uploaded.version}await api('/applications/'+created.id+'/submit','POST',{version});await refresh();setNewApplicationFiles({});setPage('Applications');setMessage('Application submitted with all required documents.')})}>Submit application <ArrowRight size={17}/></button></div>}
